using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

/// <summary>
/// Shared fixture that starts the Aspire AppHost once for the entire test run.
/// </summary>
public sealed class EvaluationHarness : IAsyncLifetime
{
    public DistributedApplication App { get; private set; } = default!;

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        App = await builder.BuildAsync();
        await App.StartAsync();
        await App.ResourceNotifications.WaitForResourceHealthyAsync("webfrontend")
            .WaitAsync(TimeSpan.FromSeconds(60));
    }

    public async ValueTask DisposeAsync()
    {
        await App.DisposeAsync();
    }
}

[CollectionDefinition(Name)]
public class EvaluationCollection : ICollectionFixture<EvaluationHarness>
{
    public const string Name = "Evaluation";
}

using Xunit;

namespace MyApp.Evaluation;

[Collection(EvaluationCollection.Name)]
public class SmokeTests
{
    private readonly EvaluationHarness _harness;

    public SmokeTests(EvaluationHarness harness)
    {
        _harness = harness;
    }

    [Fact]
    public void AppHost_Starts_Successfully()
    {
        Assert.NotNull(_harness.App);
    }
}

using System.Net.Http.Json;
using System.Text.Json;
using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.Evaluation;

[Collection(EvaluationCollection.Name)]
public class AgentEvaluationTests
{
    private readonly EvaluationHarness _harness;

    public AgentEvaluationTests(EvaluationHarness harness)
    {
        _harness = harness;
    }

    [Fact]
    public async Task Agent_Responds_To_Prompt()
    {
        using var client = _harness.App.CreateHttpClient("webfrontend");

        var request = new { prompt = "Hello, are you there?" };
        var response = await client.PostAsJsonAsync("/chat", request);

        response.EnsureSuccessStatusCode();

        var body = await response.Content.ReadAsStringAsync();
        Assert.False(string.IsNullOrWhiteSpace(body), "Agent returned an empty response.");
    }

    [Fact]
    public async Task Agent_Response_Within_Latency_Budget()
    {
        using var client = _harness.App.CreateHttpClient("webfrontend");

        var request = new { prompt = "What is 2+2?" };
        var sw = System.Diagnostics.Stopwatch.StartNew();
        var response = await client.PostAsJsonAsync("/chat", request);
        sw.Stop();

        response.EnsureSuccessStatusCode();
        Assert.True(sw.Elapsed < TimeSpan.FromSeconds(30),
            $"Response took {sw.Elapsed.TotalSeconds:F1}s, exceeding 30s budget.");
    }
}

